<?php session_start();require_once __DIR__.'/../../conn.php';require_once __DIR__.'/../../auth.php';requireStaff();require_once __DIR__.'/../../sort_utils.php';$allowed=['furniture_id'=>'ID','furniture_name'=>'Name','description'=>'Desc','price'=>'Price'];list($sort,$order)=get_sort_params($allowed,'furniture_id');$msg='';$mt='';if($_SERVER['REQUEST_METHOD']==='POST'){$fid=(int)$_POST['furniture_id'];if(isset($_POST['delete'])){$chk=mysqli_fetch_assoc(mysqli_query($conn,"SELECT COUNT(*) as cnt FROM Orders WHERE furniture_id=$fid"))['cnt'];if($chk>0){$msg="Cannot delete: {$chk} order(s) exist.";$mt='error';}else{mysqli_query($conn,"DELETE FROM Furniture_Material WHERE furniture_id=$fid");mysqli_query($conn,"DELETE FROM Furniture WHERE furniture_id=$fid");// Remove image file from /image/ folder
foreach(array('png','jpg','jpeg','gif','webp') as $ext){$imgFile=__DIR__.'/../../image/'.$fid.'.'.$ext;if(file_exists($imgFile))unlink($imgFile);}$msg='Furniture deleted.';$mt='success';}}elseif(isset($_POST['update'])){$n=trim($_POST['furniture_name']);$d=trim(isset($_POST['description'])?$_POST['description']:'');$p=(float)$_POST['price'];$st=mysqli_prepare($conn,"UPDATE Furniture SET furniture_name=?,description=?,price=? WHERE furniture_id=?");mysqli_stmt_bind_param($st,'ssdi',$n,$d,$p,$fid);if(mysqli_stmt_execute($st)){// Handle image upload: replace file in /image/ folder
if(isset($_FILES["image_file"])&&$_FILES["image_file"]["error"]===UPLOAD_ERR_OK){$ext=strtolower(pathinfo($_FILES["image_file"]["name"],PATHINFO_EXTENSION));$allowed=array("jpg","jpeg","png","gif","webp");if(in_array($ext,$allowed)&&$_FILES["image_file"]["size"]<=5*1024*1024){foreach(array('png','jpg','jpeg','gif','webp') as $oldExt){$oldFile=__DIR__.'/../../image/'.$fid.'.'.$oldExt;if(file_exists($oldFile))unlink($oldFile);}move_uploaded_file($_FILES["image_file"]["tmp_name"],__DIR__.'/../../image/'.$fid.'.'.$ext);}}$msg='Furniture updated.';$mt='success';}else{$msg='Update failed.';$mt='error';}mysqli_stmt_close($st);}}$r=mysqli_query($conn,"SELECT furniture_id,furniture_name,description,price FROM Furniture ".sort_clause($sort,$order));$rs=array();while($rw=mysqli_fetch_assoc($r))$rs[]=$rw;mysqli_free_result($r);$oc=array();$or=mysqli_query($conn,"SELECT furniture_id,COUNT(*) as cnt FROM Orders GROUP BY furniture_id");while($ow=mysqli_fetch_assoc($or))$oc[$ow['furniture_id']]=$ow['cnt'];?><!DOCTYPE html><html><head><meta charset="UTF-8"><title>Manage Furniture</title><link rel="stylesheet" href="../style.css"><style>.mc{flex:1;display:flex;flex-direction:column;overflow-y:auto;padding:24px 32px}.tw{background:#fff;border-radius:20px;padding:20px;overflow-x:auto;box-shadow:0 1px 3px rgba(0,0,0,.06)}.m{padding:12px 16px;border-radius:10px;margin-bottom:16px;font-weight:500;font-size:.9rem}.me{background:#fef2f2;color:#991b1b;border:1px solid #fecaca}.ms{background:#f0fdf4;color:#166534;border:1px solid #bbf7d0}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{padding:10px 12px;border-bottom:1px solid #e0e0e0;text-align:center}th{font-weight:500;color:#5f6368;font-size:13px}.is{padding:6px 8px;border-radius:6px;border:1px solid #dadce0;font-size:12px;width:90px}.iw{width:120px}.id{width:100px}.bs{padding:6px 12px;border-radius:16px;font-size:12px;font-weight:500;cursor:pointer;border:none;color:#fff;background:#1a73e8}.bs:hover{background:#1557b0}.bd{background:#d93025}.bd:hover{background:#b3261e}.bs:disabled{background:#9aa0a6;cursor:not-allowed}.thumb{width:80px;height:45px;object-fit:contain;border-radius:6px;border:1px solid #e0e0e0;background:#fafafa;vertical-align:middle}</style></head><body><div id="sidebar-container"></div><div class="mc"><div class="top-bar"><div class="page-title">Manage Furniture</div></div><div class="content-container"><?php if($msg):?><div class="m m<?php echo $mt[0];?>"><?php echo htmlspecialchars($msg);?></div><?php endif;?><div class="tw"><table><thead><tr><th>Img</th><th><?php echo sortable_th('furniture_id','ID',$sort,$order);?></th><th><?php echo sortable_th('furniture_name','Name',$sort,$order);?></th><th><?php echo sortable_th('description','Desc',$sort,$order);?></th><th><?php echo sortable_th('price','Price',$sort,$order);?></th><th>Stock (Derived)</th><th>Materials</th><th>Orders</th><th>Edit</th><th>Delete</th></tr></thead><tbody><?php foreach($rs as $rw):$fid=$rw['furniture_id'];$cnt=isset($oc[$fid])?$oc[$fid]:0;?><tr><td colspan="10" style="padding:0"><form method="post" enctype="multipart/form-data"><table style="width:100%;table-layout:fixed;border-collapse:collapse"><tr><td><input type="hidden" name="furniture_id" value="<?php echo $fid;?>"><img src="../../image.php?fid=<?php echo $fid;?>" class="thumb" alt=""><br><input type="file" name="image_file" accept="image/jpeg,image/png,image/gif,image/webp" style="width:100px;font-size:11px"></td><td><?php echo $fid;?></td><td><input type="text" name="furniture_name" value="<?php echo htmlspecialchars($rw['furniture_name']);?>" class="is iw" required></td><td><input type="text" name="description" value="<?php echo htmlspecialchars(isset($rw['description'])?$rw['description']:'');?>" class="is id"></td><td><input type="number" name="price" value="<?php echo $rw['price'];?>" step="0.01" class="is" required></td><td><?php $ds=getDerivedStock($conn,$fid);echo $ds;?></td><td><a href="manageFurnitureMaterials.php?fid=<?php echo $fid;?>" class="bs" style="background:#137333;text-decoration:none;display:inline-block;">🧱 Materials</a></td><td><?php echo $cnt;?></td><td><button type="submit" name="update" value="1" class="bs">Save</button></td><td><button type="submit" name="delete" value="1" class="bs bd" <?php echo $cnt>0?'disabled':'';?> onclick="<?php echo $cnt>0?'':'return confirm(\'Delete this furniture?\');';?>">Del</button> <small style="color:<?php echo $cnt>0?'#d93025':'#5f6368';?>">(<?php echo $cnt;?> order(s))</small></td></tr></table></form></td></tr><?php endforeach;mysqli_close($conn);?></tbody></table></div></div></div><script src="../sidebar.js"></script><script>loadSidebar('manage-furniture');</script></body></html>
